import { useEffect, useState } from 'react';
import { api } from '../../api/api';
import PageHeader from '../../components/PageHeader';
import Loader from '../../components/Loader';

export default function StudentProfile() {
  const [profile, setProfile] = useState(null);

  useEffect(() => { api('/students/me').then(setProfile); }, []);

  if (!profile) return <Loader />;

  const rows = [
    ['Full Name', profile.name],
    ['Admission Number', profile.admissionNo],
    ['Class', profile.className],
    ['House', profile.house],
    ['Gender', profile.gender],
    ['Date of Birth', profile.dob || '—'],
    ['Email', profile.email || '—'],
    ['Guardian', profile.guardianName || '—'],
    ['Guardian Phone', profile.guardianPhone || '—'],
    ['Address', profile.address || '—']
  ];

  return (
    <div>
      <PageHeader title="My Profile" subtitle="Your personal and academic information" />

      <div className="card profile-card">
        <div className="profile-card__head">
          <div className="avatar avatar--lg">{profile.name.charAt(0)}</div>
          <div>
            <h3>{profile.name}</h3>
            <p>{profile.className} · {profile.admissionNo}</p>
          </div>
        </div>

        <table className="table table--striped">
          <tbody>
            {rows.map(([label, value]) => (
              <tr key={label}>
                <td className="table__label">{label}</td>
                <td>{value}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
